# Apartat 1.11 (potències d'exponent zero i negatiu) dels apunts de la Unitat 1 de 4t ESO A.
# Afegit perquè la fitxa (secció 10) treballa els exponents negatius com el llibre de text. Les asserts comproven els resultats escrits a mà.
from eines4a import *

def pw(a, b, n): return Fr(a, b) ** n

# ============================================================ 1.11 Potències d'exponent zero i negatiu
s11 = box('def', L("D'on ixen l'exponent 0 i l'exponent negatiu?", '¿De dónde salen el exponente 0 y el exponente negativo?', 'Where do the exponents 0 and negative come from?'),
  P(r"Fins ara l'exponent era un nombre natural. Si volem que la regla del quocient \(a^m:a^n=a^{m-n}\) funcione sempre, encara que l'exponent de baix siga igual o més gran, ens apareixen l'exponent 0 i els exponents negatius:",
    r"Hasta ahora el exponente era un número natural. Si queremos que la regla del cociente \(a^m:a^n=a^{m-n}\) funcione siempre, aunque el exponente de abajo sea igual o mayor, nos aparecen el exponente 0 y los exponentes negativos:",
    r"Until now the exponent was a natural number. If we want the quotient rule \(a^m:a^n=a^{m-n}\) to work every time, even when the bottom exponent is equal or larger, we get the exponent 0 and negative exponents:")
  + r'\[\frac{2^3}{2^3}=\frac{8}{8}=1,\qquad\frac{2^3}{2^3}=2^{3-3}=2^0\ \ \Rightarrow\ \ 2^0=1\]'
  + r'\[\frac{2^3}{2^5}=\frac{\cancel{2}\cdot\cancel{2}\cdot\cancel{2}}{\cancel{2}\cdot\cancel{2}\cdot\cancel{2}\cdot2\cdot2}=\frac{1}{2^2},\qquad\frac{2^3}{2^5}=2^{3-5}=2^{-2}\ \ \Rightarrow\ \ 2^{-2}=\frac{1}{2^2}=\frac{1}{4}\]')
ck(Fr(2 ** 3, 2 ** 5), pw(2, 1, -2)); ck(pw(2, 1, -2), Fr(1, 4))
s11 += box('prop', L('Exponent zero i exponent negatiu', 'Exponente cero y exponente negativo', 'Zero and negative exponents'),
  table([L('Regla', 'Regla', 'Rule'), L('Què vol dir', 'Qué quiere decir', 'Meaning'), L('Exemples', 'Ejemplos', 'Examples')],
        [[r'\(a^0=1\)', L('Qualsevol base (diferent de 0) elevada a 0 val 1.', 'Cualquier base (distinta de 0) elevada a 0 vale 1.', 'Any base (other than 0) to the power 0 is 1.'), r'\(7^0=1,\quad(-3)^0=1,\quad\left(\frac{2}{5}\right)^0=1\)'],
         [r'\(a^{-n}=\dfrac{1}{a^n}\)', L("L'exponent negatiu <strong>inverteix</strong> la base; després elevem a l'exponent positiu.", 'El exponente negativo <strong>invierte</strong> la base; después elevamos al exponente positivo.', 'A negative exponent <strong>flips</strong> the base; then raise it to the positive exponent.'), r'\(5^{-2}=\frac{1}{5^2}=\frac{1}{25},\quad10^{-3}=\frac{1}{1000}=0{,}001\)'],
         [r'\(\left(\dfrac{a}{b}\right)^{-n}=\left(\dfrac{b}{a}\right)^{n}\)', L('Amb una fracció: li donem la volta i canviem el signe de l\'exponent.', 'Con una fracción: le damos la vuelta y cambiamos el signo del exponente.', 'With a fraction: turn it upside down and change the sign of the exponent.'), r'\(\left(\frac{2}{3}\right)^{-3}=\left(\frac{3}{2}\right)^3=\frac{27}{8},\quad\left(\frac{1}{4}\right)^{-2}=4^2=16\)']], 'data')
  + note(r"L'exponent negatiu <strong>no</strong> fa negatiu el resultat: \(\ 2^{-3}=\frac{1}{8}\), no \(-8\) ni \(-6\). El signe del resultat depén de la base: \((-2)^{-3}=\frac{1}{(-2)^3}=-\frac{1}{8}\) (base negativa, exponent senar) i \((-3)^{-2}=\frac{1}{9}\) (exponent parell).",
         r"El exponente negativo <strong>no</strong> hace negativo el resultado: \(\ 2^{-3}=\frac{1}{8}\), no \(-8\) ni \(-6\). El signo del resultado depende de la base: \((-2)^{-3}=\frac{1}{(-2)^3}=-\frac{1}{8}\) (base negativa, exponente impar) y \((-3)^{-2}=\frac{1}{9}\) (exponente par).",
         r"A negative exponent does <strong>not</strong> make the result negative: \(\ 2^{-3}=\frac{1}{8}\), not \(-8\) or \(-6\). The sign depends on the base: \((-2)^{-3}=\frac{1}{(-2)^3}=-\frac{1}{8}\) (negative base, odd exponent) and \((-3)^{-2}=\frac{1}{9}\) (even exponent).", '⚠️'))
ck(pw(5, 1, -2), Fr(1, 25)); ck(pw(10, 1, -3), Fr(1, 1000)); ck(pw(2, 3, -3), Fr(27, 8)); ck(pw(1, 4, -2), 16); ck(pw(-2, 1, -3), Fr(-1, 8)); ck(pw(-3, 1, -2), Fr(1, 9))
s11 += box('def', L('Les propietats continuen valent', 'Las propiedades siguen valiendo', 'The laws still work'),
  P(r"Totes les propietats de l'apartat anterior valen també amb exponents enters (positius, zero o negatius). Només cal anar amb compte amb els signes en sumar, restar i multiplicar els exponents:",
    r"Todas las propiedades del apartado anterior valen también con exponentes enteros (positivos, cero o negativos). Solo hay que tener cuidado con los signos al sumar, restar y multiplicar los exponentes:",
    r"All the laws in the previous section also hold with integer exponents (positive, zero or negative). Just be careful with signs when adding, subtracting and multiplying exponents:")
  + r'\[3^{-4}\cdot3^{6}=3^{-4+6}=3^2\qquad 5^{2}:5^{-3}=5^{2-(-3)}=5^{5}\qquad \left(2^{-3}\right)^{2}=2^{-6}\qquad 4^{-2}\cdot5^{-2}=20^{-2}\]'
  + note(r"Per a simplificar expressions amb bases diferents, descompon les bases en factors primers i ajunta cada primer: \(\ \dfrac{4^{-1}\cdot8^2}{2^3}=\dfrac{2^{-2}\cdot2^6}{2^3}=2^{-2+6-3}=2^1=2\).",
         r"Para simplificar expresiones con bases distintas, descompón las bases en factores primos y junta cada primo: \(\ \dfrac{4^{-1}\cdot8^2}{2^3}=\dfrac{2^{-2}\cdot2^6}{2^3}=2^{-2+6-3}=2^1=2\).",
         r"To simplify expressions with different bases, write the bases as prime factors and collect each prime: \(\ \dfrac{4^{-1}\cdot8^2}{2^3}=\dfrac{2^{-2}\cdot2^6}{2^3}=2^{-2+6-3}=2^1=2\)."))
ck(pw(3, 1, -4) * 3 ** 6, 9); ck(Fr(5 ** 2) / pw(5, 1, -3), 5 ** 5); ck(pw(4, 1, -2) * pw(5, 1, -2), pw(20, 1, -2)); ck(pw(4, 1, -1) * 8 ** 2 / 2 ** 3, 2)
s11 += level(1, 1,
  prob(L(r"Calcula: a) \(3^{-2}\) &nbsp; b) \((-4)^{-1}\) &nbsp; c) \(\left(\frac{3}{5}\right)^{-2}\) &nbsp; d) \(\left(-\frac{1}{2}\right)^{-3}\) &nbsp; e) \(12^0\)", r"Calcula: a) \(3^{-2}\) &nbsp; b) \((-4)^{-1}\) &nbsp; c) \(\left(\frac{3}{5}\right)^{-2}\) &nbsp; d) \(\left(-\frac{1}{2}\right)^{-3}\) &nbsp; e) \(12^0\)", r"Work out: a) \(3^{-2}\) &nbsp; b) \((-4)^{-1}\) &nbsp; c) \(\left(\frac{3}{5}\right)^{-2}\) &nbsp; d) \(\left(-\frac{1}{2}\right)^{-3}\) &nbsp; e) \(12^0\)"),
       r'\[\text{a) }\frac{1}{3^2}=\boxed{\frac{1}{9}}\qquad\text{b) }\boxed{-\frac{1}{4}}\qquad\text{c) }\left(\frac{5}{3}\right)^2=\boxed{\frac{25}{9}}\qquad\text{d) }(-2)^3=\boxed{-8}\qquad\text{e) }\boxed{1}\]'))
ck(pw(3, 1, -2), Fr(1, 9)); ck(pw(-4, 1, -1), Fr(-1, 4)); ck(pw(3, 5, -2), Fr(25, 9)); ck(pw(-1, 2, -3), -8)
s11 += level(2, 2,
  prob(L(r"Escriu com una sola potència: \(\ 2^{-5}\cdot2^{3}:2^{-4}\) &nbsp; i &nbsp; \(\left[\left(\frac{3}{4}\right)^{-2}\right]^{3}\cdot\left(\frac{3}{4}\right)^{4}\).", r"Escribe como una sola potencia: \(\ 2^{-5}\cdot2^{3}:2^{-4}\) &nbsp; y &nbsp; \(\left[\left(\frac{3}{4}\right)^{-2}\right]^{3}\cdot\left(\frac{3}{4}\right)^{4}\).", r"Write as a single power: \(\ 2^{-5}\cdot2^{3}:2^{-4}\) &nbsp; and &nbsp; \(\left[\left(\frac{3}{4}\right)^{-2}\right]^{3}\cdot\left(\frac{3}{4}\right)^{4}\)."),
       r'\[2^{-5+3-(-4)}=\boxed{2^{2}}\qquad\left(\frac{3}{4}\right)^{-6}\cdot\left(\frac{3}{4}\right)^{4}=\boxed{\left(\frac{3}{4}\right)^{-2}}=\left(\frac{4}{3}\right)^{2}=\frac{16}{9}\]'),
  prob(L(r"Calcula: \(\ 2^{-1}+4^{-1}-\left(\frac{2}{3}\right)^{-1}\).", r"Calcula: \(\ 2^{-1}+4^{-1}-\left(\frac{2}{3}\right)^{-1}\).", r"Work out: \(\ 2^{-1}+4^{-1}-\left(\frac{2}{3}\right)^{-1}\)."),
       P(r"Amb sumes i restes no hi ha cap propietat: calculem cada potència i operem les fraccions.", r"Con sumas y restas no hay ninguna propiedad: calculamos cada potencia y operamos las fracciones.", r"There is no law for sums and differences: work out each power and add the fractions."),
       r'\[\frac{1}{2}+\frac{1}{4}-\frac{3}{2}=\frac{2}{4}+\frac{1}{4}-\frac{6}{4}=\boxed{-\frac{3}{4}}\]'))
ck(pw(2, 1, -5) * 2 ** 3 / pw(2, 1, -4), 4); ck(pw(3, 4, -2) ** 3 * pw(3, 4, 4), Fr(16, 9)); ck(pw(2, 1, -1) + pw(4, 1, -1) - pw(2, 3, -1), Fr(-3, 4))
s11 += level(3, 4,
  prob(L(r"Simplifica descomponent en factors primers: \(\ \dfrac{9^{-1}\cdot6^{3}}{2^{4}\cdot3^{-2}}\).", r"Simplifica descomponiendo en factores primos: \(\ \dfrac{9^{-1}\cdot6^{3}}{2^{4}\cdot3^{-2}}\).", r"Simplify using prime factors: \(\ \dfrac{9^{-1}\cdot6^{3}}{2^{4}\cdot3^{-2}}\)."),
       P(r"\(9^{-1}=(3^2)^{-1}=3^{-2}\) i \(6^3=2^3\cdot3^3\). Ajuntem els 2 i els 3:", r"\(9^{-1}=(3^2)^{-1}=3^{-2}\) y \(6^3=2^3\cdot3^3\). Juntamos los 2 y los 3:", r"\(9^{-1}=(3^2)^{-1}=3^{-2}\) and \(6^3=2^3\cdot3^3\). Collect the 2s and the 3s:"),
       r'\[\frac{3^{-2}\cdot2^{3}\cdot3^{3}}{2^{4}\cdot3^{-2}}=2^{3-4}\cdot3^{-2+3-(-2)}=2^{-1}\cdot3^{3}=\boxed{\frac{27}{2}}\]'),
  prob(L(r"Calcula: \(\ \left[\left(\frac{1}{3}\right)^{-2}-(-2)^{3}\right]^{-1}\cdot\left(\frac{5}{2}\right)^{-2}\).", r"Calcula: \(\ \left[\left(\frac{1}{3}\right)^{-2}-(-2)^{3}\right]^{-1}\cdot\left(\frac{5}{2}\right)^{-2}\).", r"Work out: \(\ \left[\left(\frac{1}{3}\right)^{-2}-(-2)^{3}\right]^{-1}\cdot\left(\frac{5}{2}\right)^{-2}\)."),
       r'\[\left[9-(-8)\right]^{-1}\cdot\left(\frac{2}{5}\right)^{2}=17^{-1}\cdot\frac{4}{25}=\frac{1}{17}\cdot\frac{4}{25}=\boxed{\frac{4}{425}}\]'))
ck(pw(9, 1, -1) * 6 ** 3 / (2 ** 4 * pw(3, 1, -2)), Fr(27, 2)); ck((pw(1, 3, -2) - (-2) ** 3) ** -1 * pw(5, 2, -2), Fr(4, 425))
s11 += practice([
  ('★', L(r"Calcula: a) \(10^{-2}\) &nbsp; b) \((-5)^{-2}\) &nbsp; c) \(\left(\frac{1}{3}\right)^{-3}\) &nbsp; d) \(\left(-\frac{4}{7}\right)^{-1}\) &nbsp; e) \(\left(\frac{9}{11}\right)^{0}\)", r"Calcula: a) \(10^{-2}\) &nbsp; b) \((-5)^{-2}\) &nbsp; c) \(\left(\frac{1}{3}\right)^{-3}\) &nbsp; d) \(\left(-\frac{4}{7}\right)^{-1}\) &nbsp; e) \(\left(\frac{9}{11}\right)^{0}\)", r"Work out: a) \(10^{-2}\) &nbsp; b) \((-5)^{-2}\) &nbsp; c) \(\left(\frac{1}{3}\right)^{-3}\) &nbsp; d) \(\left(-\frac{4}{7}\right)^{-1}\) &nbsp; e) \(\left(\frac{9}{11}\right)^{0}\)")),
  ('★★', L(r"f) Ordena de menor a major: \(3^{-1}\), \(3^{0}\), \((-3)^{-1}\), \(3^{-2}\) &nbsp; g) Escriu com una sola potència: \(7^{4}:7^{-2}\cdot7^{-5}\)", r"f) Ordena de menor a mayor: \(3^{-1}\), \(3^{0}\), \((-3)^{-1}\), \(3^{-2}\) &nbsp; g) Escribe como una sola potencia: \(7^{4}:7^{-2}\cdot7^{-5}\)", r"f) Order from smallest to largest: \(3^{-1}\), \(3^{0}\), \((-3)^{-1}\), \(3^{-2}\) &nbsp; g) Write as a single power: \(7^{4}:7^{-2}\cdot7^{-5}\)")),
  ('★★★', L(r"h) Expressa com una potència de base 3: \(\ \dfrac{27^{2}\cdot9^{-3}}{3^{-1}}\) &nbsp; i) Calcula: \(\ \left(\frac{1}{2}-\frac{3}{4}\right)^{-2}+\left(\frac{2}{3}\right)^{-1}\)", r"h) Expresa como una potencia de base 3: \(\ \dfrac{27^{2}\cdot9^{-3}}{3^{-1}}\) &nbsp; i) Calcula: \(\ \left(\frac{1}{2}-\frac{3}{4}\right)^{-2}+\left(\frac{2}{3}\right)^{-1}\)", r"h) Write as a power of 3: \(\ \dfrac{27^{2}\cdot9^{-3}}{3^{-1}}\) &nbsp; i) Work out: \(\ \left(\frac{1}{2}-\frac{3}{4}\right)^{-2}+\left(\frac{2}{3}\right)^{-1}\)"))],
  P(r"a) \(\frac{1}{100}=0{,}01\) &nbsp; b) \(\frac{1}{25}\) &nbsp; c) \(27\) &nbsp; d) \(-\frac{7}{4}\) &nbsp; e) \(1\) &nbsp; f) \((-3)^{-1}<3^{-2}<3^{-1}<3^{0}\) &nbsp; g) \(7^{4+2-5}=7^{1}\) &nbsp; h) \(\frac{3^{6}\cdot3^{-6}}{3^{-1}}=3^{1}\) &nbsp; i) \(\left(-\frac{1}{4}\right)^{-2}+\frac{3}{2}=16+\frac{3}{2}=\frac{35}{2}\)",
    r"a) \(\frac{1}{100}=0{,}01\) &nbsp; b) \(\frac{1}{25}\) &nbsp; c) \(27\) &nbsp; d) \(-\frac{7}{4}\) &nbsp; e) \(1\) &nbsp; f) \((-3)^{-1}<3^{-2}<3^{-1}<3^{0}\) &nbsp; g) \(7^{4+2-5}=7^{1}\) &nbsp; h) \(\frac{3^{6}\cdot3^{-6}}{3^{-1}}=3^{1}\) &nbsp; i) \(\left(-\frac{1}{4}\right)^{-2}+\frac{3}{2}=16+\frac{3}{2}=\frac{35}{2}\)",
    r"a) \(\frac{1}{100}=0.01\) &nbsp; b) \(\frac{1}{25}\) &nbsp; c) \(27\) &nbsp; d) \(-\frac{7}{4}\) &nbsp; e) \(1\) &nbsp; f) \((-3)^{-1}<3^{-2}<3^{-1}<3^{0}\) &nbsp; g) \(7^{4+2-5}=7^{1}\) &nbsp; h) \(\frac{3^{6}\cdot3^{-6}}{3^{-1}}=3^{1}\) &nbsp; i) \(\left(-\frac{1}{4}\right)^{-2}+\frac{3}{2}=16+\frac{3}{2}=\frac{35}{2}\)"))
ck(pw(-5, 1, -2), Fr(1, 25)); ck(pw(1, 3, -3), 27); ck(pw(-4, 7, -1), Fr(-7, 4))
assert sorted([pw(3, 1, -1), Fr(1), pw(-3, 1, -1), pw(3, 1, -2)]) == [pw(-3, 1, -1), pw(3, 1, -2), pw(3, 1, -1), 1]
ck(Fr(7 ** 4) / pw(7, 1, -2) * pw(7, 1, -5), 7); ck(Fr(27 ** 2) * pw(9, 1, -3) / pw(3, 1, -1), 3); ck((Fr(1, 2) - Fr(3, 4)) ** -2 + pw(2, 3, -1), Fr(35, 2))
